  function trapFocus(e) {
    if (e.key !== 'Tab') return;

    const focusable = Array.from(
      dialog.querySelectorAll(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
      )
    ).filter(el => !el.disabled && el.offsetParent !== null);

    if (focusable.length === 0) return;

    const first = focusable[0];
    const last  = focusable[focusable.length - 1];

    if (e.shiftKey) {
      if (document.activeElement === first) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  }

  // ── Event listeners ──────────────────────────────────────────

  triggers.forEach(btn => btn.addEventListener('click', () => openDialog(btn)));

  // Cancel button and the ✕ close button
  cancelBtn.addEventListener('click', closeDialog);
  document.getElementById('modal-close-btn').addEventListener('click', closeDialog);

  // Confirm / destructive action
  confirmBtn.addEventListener('click', () => {
    // Replace with actual delete logic as needed
    closeDialog();
