  dialog.addEventListener('cancel', (e) => {
    // 'cancel' fires before 'close' when Escape is pressed
    e.preventDefault(); // prevent default so we control the close
    closeDialog();
  });

  // Backdrop click closes the dialog
  dialog.addEventListener('click', (e) => {
